  child=dict(empty,id=id,officialName=f'{name} of {r["officialName"].lower()}',latinName=latin or None,synonyms=[],anatomicalSystem='Skeletal',region=r['region'],kind='landmark',parentId=r['id'],hierarchyPath=r['hierarchyPath']+[dict(id=id,name=name)],description=[fact(text,ref)],location=[fact(f'This feature belongs to the {r["officialName"].lower()}.',ref)],anatomicalRelations=[],modelIds=[],meshIds=[],sourceReferences=[ref]+(['fipat'] if latin else []),verificationStatus='source-checked',lastReviewedAt=DATE,version=1,laterality=r['laterality'],clinicalReview={'status':'pending'},populationBatch='upper-limb-001',contentLicense=r['contentLicense'])
