for name,ids,latin in [('radius',[('FMA23465','left'),('FMA23464','right')],'Radius'),('ulna',[('FMA23468','left'),('FMA23467','right')],'Ulna')]:
 ref='gray-'+name
 for id,side in ids:
  r=bone(id,side,name,latin)
  if name=='radius':
   r['description']=[fact(f'The {side} radius lies on the thumb side of the forearm in anatomical position. A small proximal head and neck lead into a curved shaft that expands substantially at the wrist. The bone articulates with the humerus and ulna proximally, with the ulna distally and with the carpal region.','gray-radius'),fact('The proximal head has a superior articular depression and a smooth circumference. Below the neck, the radial tuberosity provides a biceps attachment. The shaft has anterior, posterior and lateral surfaces and an interosseous border facing the ulna. Distally, carpal facets and the ulnar notch face different articulating structures.','gray-radius')]
   parts=[('head','Head','Caput radii','The superior depression articulates with the humeral capitulum; its circumference relates to the radial notch and annular ligament.'),('neck','Neck','Collum radii','The narrowed segment between the radial head and shaft is adjacent to the proximal supinator attachment.'),('body','Body','Corpus radii','The bowed shaft broadens distally and has three surfaces separated by anterior, posterior and interosseous borders.')]
   landmarks=[('tuberosity','Radial tuberosity','Tuberositas radii','The rough posterior part receives biceps; an adjacent smooth region is related to the tendon bursa.'),('styloid','Styloid process','Processus styloideus radii','The lateral distal projection provides ligament attachment and lies near the distal brachioradialis insertion.'),('ulnar-notch','Ulnar notch','Incisura ulnaris radii','The medial distal concavity articulates with the ulnar head at the distal radioulnar joint.'),('dorsal-tubercle','Dorsal tubercle',None,'This distal dorsal landmark redirects the extensor pollicis longus tendon.'),('carpal-facets','Carpal articular surface',None,'The distal articular region has facets for the scaphoid laterally and lunate medially.')]
   surf=[('anterior','Anterior surface',None,'The proximal anterior shaft gives origin to flexor pollicis longus; the distal anterior region receives pronator quadratus.'),('posterior','Posterior surface',None,'The posterior shaft relates to supinator proximally and origins of thumb extensors/abductors more distally.'),('lateral','Lateral surface',None,'The lateral shaft receives supinator proximally and pronator teres near its middle.'),('anterior-border','Anterior border',None,'This border separates anterior and lateral surfaces and extends toward the base of the styloid.'),('posterior-border','Posterior border',None,'The boundary between posterior and lateral surfaces is most distinct in the middle shaft.'),('interosseous-border','Interosseous border',None,'The sharp medial edge faces the ulna and anchors the interosseous membrane.')]
   r['attachments']=[fact('Biceps attaches to the radial tuberosity. Supinator, pronator teres and pronator quadratus attach at distinct proximal, middle and distal regions. Brachioradialis inserts near the radial styloid. The interosseous membrane anchors along the medial shaft border.',ref)]
   r['articulations']=[fact('The head meets the humeral capitulum and ulnar radial notch. Distally, the ulnar notch meets the ulnar head, while the carpal facets meet scaphoid and lunate.',ref)]
   r['structureAndFunction']=[fact('Rotation at the radioulnar joints allows the radius and attached hand to move around the ulna during pronation and supination. The expanded distal end provides an important load-bearing interface with the carpus.','forearm-modern')]
   r['clinicalNotes']=[fact('Radius fractures can involve the proximal head, shaft or distal articular region. Assessment must consider the adjacent joints and associated radioulnar instability rather than treating the visible break as an isolated bone lesion.','forearm-modern')]
   r['detailedSections']=[section('bloodSupply','Arterial supply','Radial and radial recurrent vessels contribute proximally. Radial and interosseous arterial contributions supply more distal regions.','radius-modern'),section('lymphaticDrainage','Lymphatic drainage','Deep lymphatic vessels accompany deep veins toward humeral axillary nodes. This is regional drainage information, not a segmented lymphatic mesh in this atlas.','radius-modern'),section('ossification','Ossification','The classical description identifies a shaft centre and one epiphyseal centre at either end. Historical age ranges are not reproduced as modern diagnostic standards.','gray-radius')]
  else:
   r['description']=[fact(f'The {side} ulna is the medial forearm long bone in anatomical position. Its large proximal end forms the principal bony hinge with the humeral trochlea. In contrast with the radius, the shaft narrows toward a comparatively small distal head and styloid.','gray-ulna'),fact('The olecranon and coronoid process bound the trochlear notch. A separate radial notch on the lateral proximal end articulates with the radial head. The shaft has anterior, posterior and medial surfaces, an interosseous border facing the radius and a readily accessible posterior border. An articular disc separates the distal ulna from direct carpal articulation.','gray-ulna')]
   parts=[('proximal','Proximal end',None,'The expanded proximal end contains the olecranon, coronoid process, trochlear notch and radial notch.'),('body','Body','Corpus ulnae','The shaft tapers distally and has three surfaces and three borders.'),('head','Head','Caput ulnae','The small distal head articulates with the ulnar notch of the radius and relates inferiorly to the articular disc.')]
   landmarks=[('olecranon','Olecranon','Olecranon','The proximal posterior process receives triceps and enters the humeral olecranon fossa during extension.'),('coronoid','Coronoid process','Processus coronoideus ulnae','The proximal anterior projection contributes to the trochlear notch and enters the humeral coronoid fossa in flexion.'),('trochlear-notch','Trochlear notch','Incisura trochlearis','The large proximal articular concavity embraces the humeral trochlea.'),('radial-notch','Radial notch','Incisura radialis ulnae','The lateral proximal articular surface receives the radial head circumference; its margins relate to the annular ligament.'),('tuberosity','Ulnar tuberosity','Tuberositas ulnae','An anterior roughened area distal to the coronoid process receives part of brachialis.'),('styloid','Styloid process','Processus styloideus ulnae','The distal medial projection is distinct from the adjacent articular head.')]
   surf=[('anterior','Anterior surface',None,'The anterior shaft provides origins for flexor digitorum profundus and, in its distal part, pronator quadratus.'),('posterior','Posterior surface',None,'The posterior surface supplies separate attachment regions for anconeus, supinator and several deep extensor muscles.'),('medial','Medial surface',None,'The broad upper medial surface gives origin to flexor digitorum profundus; the distal medial region becomes subcutaneous.'),('anterior-border','Anterior border',None,'This edge separates anterior and medial surfaces, extending from the coronoid region toward the styloid.'),('posterior-border','Posterior border',None,'This edge extends from the posterior olecranon toward the distal bone and provides a shared fascial attachment line.'),('interosseous-border','Interosseous border',None,'The lateral shaft edge anchors the interosseous membrane and faces the radius.')]
   r['attachments']=[fact('Triceps inserts on the olecranon and brachialis on the coronoid/tuberosity region. Flexor digitorum profundus and pronator quadratus arise from anterior/medial shaft regions. The interosseous membrane attaches to the lateral border.',ref)]
   r['articulations']=[fact('The trochlear notch meets the humeral trochlea. The proximal radial notch and distal head articulate with the radius at separate radioulnar joints. An articular disc intervenes between the distal ulna and carpus.',ref)]
   r['structureAndFunction']=[fact('The proximal ulna provides elbow stability while its relationship to the radius permits forearm rotation. Muscle and membrane attachments integrate both bones rather than allowing either shaft to function in isolation.','forearm-modern')]
   r['clinicalNotes']=[fact('Forearm injury assessment includes associated radial-head and radioulnar-joint lesions. An ulnar fracture with proximal radial dislocation is a different injury pattern from an isolated shaft fracture.','monteggia')]
   r['detailedSections']=[section('surfaceAnatomy','Surface anatomy','The olecranon and posterior ulnar border are superficial bony reference points. Their relationship changes with elbow position, while the deeper articular notch cannot be assessed by simply viewing the skin contour.','gray-ulna'),section('ossification','Ossification','The classical pattern comprises a shaft centre and proximal/distal epiphyseal centres. Fusion and appearance timing require contemporary validation before clinical use.','gray-ulna')]
  r['classification']=[fact('Long bone of the appendicular skeleton.',ref)];r['location']=[fact(f'{side.title()} forearm, between elbow and wrist.',ref)]
  features(r,'parts',parts,ref);features(r,'surfaces',surf,ref);features(r,'landmarks',landmarks,ref)
  counterpart=('FMA23468' if side=='left' else 'FMA23467') if name=='radius' else ('FMA23465' if side=='left' else 'FMA23464')
  r['anatomicalRelations']=[dict(fact('The other forearm bone is linked on the same anatomical side; the interosseous membrane connects their facing shaft borders.',ref),targetId=counterpart,lateralityConstraint='ipsilateral',label=f'{side.title()} '+('ulna' if name=='radius' else 'radius'))]
  finish(r)

